              onChange={(e) => set("status", e.target.value)}
              className={inputBase}
            >
              {PRODUCT_STATUSES.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
            <div className="mt-3 border-t border-black/5 pt-2">
              {Toggle("featuredProduct", "Featured product")}
