(()=>{
  const cards=[...document.querySelectorAll('.card-surface')];
  const timelineCards=cards.filter(c=>/^(2018|2020|2023|2025)/.test(c.textContent.trim()));
  const last=timelineCards[timelineCards.length-1];
  if(!last) return {found:false, total:cards.length, sample:cards.slice(0,3).map(c=>c.textContent.slice(0,20))};
  const container=last.parentElement;
  const grid=container.parentElement;
  const gcs=getComputedStyle(grid);
  return {
    timelineCardCount: timelineCards.length,
    cardHeights: timelineCards.map(c=>Math.round(c.getBoundingClientRect().height)),
    lastCardText: last.textContent.trim().slice(0,40),
    containerClass: container.className,
    containerHeight: Math.round(container.getBoundingClientRect().height),
    containerDisplay: getComputedStyle(container).display,
    gridClass: grid.className,
    gridDisplay: gcs.display,
    gridAlignItems: gcs.alignItems,
    leftColHeight: Math.round(grid.children[0].getBoundingClientRect().height),
    rightColHeight: Math.round(grid.children[1].getBoundingClientRect().height),
  };
})()

