    .from(PRODUCTS_TABLE)
    .select("*")
    .eq("slug", slug)
    .eq("status", "Active")
    .maybeSingle();

  if (error) {
    return (demoProducts as Product[]).find((p) => p.slug === slug);
  }
  if (!data) return undefined;
  return rowToProduct(data);
}

/** Admin listing — every status. */
export async function getAdminProductsState(): Promise<AdminProductsState> {
