  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-plex-mono",
});

export const dynamic = "force-dynamic";

export default async function PanelLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [{ products }, categories] = await Promise.all([
    getAdminProductsState(),
    getCategories(),
