                <div key={a.id} className="flex gap-3 text-sm">
                  <span
                    className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${ACTIVITY_DOT[a.action] ?? "bg-[#8a857c]"}`}
                  />
                  <div className="min-w-0">
