/* Base element resets live in @layer base so Tailwind utilities (bg-*,
   text-*, rounded-*) reliably win over them. Without this layer these
   unlayered rules override utilities and cause invisible/dark buttons. */
@layer base {
  * {
    box-sizing: border-box;
    border-radius: 0;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    margin: 0;
    background: var(--color-cream);
    color: var(--color-black);
    font-family: var(--font-body), sans-serif;
  }

  a {
