22	const bulkSchema = z.discriminatedUnion("action", [
23	  z.object({ action: z.literal("delete"), ids: z.array(z.string()).min(1) }),
24	  z.object({
25	    action: z.literal("setStatus"),
26	    ids: z.array(z.string()).min(1),
27	    status: z.enum(PRODUCT_STATUSES),
