import Link from "next/link";
import { PageHero } from "@/components/ui/PageHero";
import { getAllProducts } from "@/lib/products";
import type { Product } from "@/lib/product-schema";
import { slugify } from "@/lib/utils";

export const dynamic = "force-dynamic";

const FALLBACK_IMAGE = "/icon.png";

function parentCategory(p: Product): string {
  return (p.categoryPath || p.category || "").split(" / ")[0].trim() || "Catalogue";
}

function ProductCard({ product }: { product: Product }) {
  const sub = (product.categoryPath || "").split(" / ")[1];
  return (
    <Link href={`/products/${product.slug}`} className="card-surface overflow-hidden">
      <Image
        src={product.mainImageLink || FALLBACK_IMAGE}
        alt={product.altTextMainImage || product.title}
        width={900}
        height={1100}
        className="h-[420px] w-full object-cover"
      />
      <div className="p-6">
        <p className="eyebrow">{sub || parentCategory(product)}</p>
        <h2 className="font-heading mt-3 text-3xl">{product.title}</h2>
        <p className="body-copy mt-3">{product.shortDescription}</p>
        <span className="mt-5 block text-sm text-[var(--color-mid)]">
          {product.priceNote || "Price on request"}
        </span>
        <span className="mt-4 inline-block text-sm uppercase tracking-[0.15em] text-[var(--color-gold)]">
          View Product Page
        </span>
      </div>
    </Link>
  );
}

export default async function ProductsPage() {
  const products = await getAllProducts();

  // Group by top-level category, preserving first-seen order.
  const groups = new Map<string, Product[]>();
  for (const p of products) {
    const key = parentCategory(p);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(p);
  }
  const sections = [...groups.entries()];
  const grouped = sections.length > 1;

  return (
    <>
      <PageHero
        label="Our Collections"
        title="Bespoke furniture, organised by the room it's made for."
        description="Browse the OSIMIRI catalogue across living, dining, bedroom, workspace, and more — each piece made to order and customisable to your space."
        image={products[0]?.mainImageLink || FALLBACK_IMAGE}
      />

      {grouped ? (
        <nav className="border-b border-black/10 bg-[var(--color-warm-white)]">
          <div className="container-shell flex flex-wrap gap-x-6 gap-y-2 py-5 text-sm uppercase tracking-[0.14em] text-[var(--color-mid)]">
            {sections.map(([name]) => (
              <a key={name} href={`#${slugify(name)}`} className="hover:text-[var(--color-black)]">
                {name}
              </a>
            ))}
          </div>
        </nav>
      ) : null}

      <section className="section-space">
        <div className="container-shell space-y-16">
          {grouped ? (
            sections.map(([name, items]) => (
              <div key={name} id={slugify(name)} className="scroll-mt-28">
                <h2 className="font-heading text-3xl md:text-4xl">{name}</h2>
                <div className="mt-8 grid gap-6 md:grid-cols-2 xl:grid-cols-3">
                  {items.map((product) => (
                    <ProductCard key={product.slug} product={product} />
                  ))}
                </div>
              </div>
            ))
          ) : (
            <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
              {products.map((product) => (
                <ProductCard key={product.slug} product={product} />
              ))}
            </div>
          )}
        </div>
      </section>
    </>
  );
}

"use client";

import Link from "next/link";
import { Menu, Search, X } from "lucide-react";
import { useState } from "react";
import { usePathname } from "next/navigation";
import { EnquiryButton } from "@/components/forms/EnquiryButton";
import { buttonClasses } from "@/components/ui/Button";
import { cn } from "@/lib/utils";

const links = [
  ["Collections", "/collections"],
  ["Projects", "/projects"],
  ["Custom Furniture", "/custom-furniture"],
  ["Manufacturing", "/manufacturing"],
  ["Architects", "/architects"],
  ["About", "/about"],
  ["Contact", "/contact"],
];

export function Navbar() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);

  return (
    <header
      className={cn(
        "sticky top-0 z-50 border-b border-[color:color-mix(in_srgb,var(--color-black)_12%,transparent)] bg-white/96 backdrop-blur-md transition duration-300",
      )}
    >
      <div className="container-shell flex h-24 items-center justify-between gap-4 px-2 xl:gap-6">
        <Link href="/" className="flex min-w-[128px] flex-col justify-center lg:min-w-[150px] xl:min-w-[170px]">
          <span className="font-heading text-[28px] tracking-[0.14em] text-[var(--color-black)] lg:text-[34px] xl:text-[38px]">
            OSIMIRI
          </span>
          <span className="text-[10px] uppercase tracking-[0.22em] text-[var(--color-gold)] lg:text-[11px]">
            Luxury Redefined
          </span>
        </Link>
        <nav className="hidden items-center gap-1 text-sm text-[var(--color-mid)] xl:gap-2 lg:flex">
          {links.map(([label, href]) => (
            <Link
              key={href}
              href={href}
              className={cn(
                "rounded-[2px] px-3 py-2 transition-colors duration-200",
                pathname === href
                  ? "bg-[color:color-mix(in_srgb,var(--color-gold-light)_45%,transparent)] text-[var(--color-black)]"
                  : "hover:bg-[color:color-mix(in_srgb,var(--color-gold-light)_35%,transparent)] hover:text-[var(--color-black)]",
              )}
            >
              {label}
            </Link>
          ))}
        </nav>
        <div className="hidden shrink-0 items-center gap-3 lg:flex">
          <Link href="/search?q=" className={buttonClasses("ghost", "no-underline hover:text-[var(--color-black)]")}>
            <Search size={16} /> Search
          </Link>
          <EnquiryButton
            label="Enquire Now"
            className="min-w-[154px] shrink-0 rounded-[2px] border border-[var(--color-black)] bg-[var(--color-gold-light)] px-6 py-3 font-medium text-[11px] tracking-[0.18em] text-black shadow-none hover:border-[var(--color-gold)] hover:bg-[var(--color-warm-white)] hover:text-black"
          />
        </div>
        <button
          type="button"
          className="text-[var(--color-black)] lg:hidden"
          onClick={() => setOpen((value) => !value)}
        >
          {open ? <X /> : <Menu />}
        </button>
      </div>
      {open ? (
        <div className="border-t border-[color:color-mix(in_srgb,var(--color-black)_12%,transparent)] bg-white lg:hidden">
          <div className="container-shell flex flex-col gap-4 py-6">
            {links.map(([label, href]) => (
              <Link key={href} href={href} onClick={() => setOpen(false)} className="text-[var(--color-black)]">
                {label}
              </Link>
            ))}
            <EnquiryButton
              label="Enquire Now"
              className="w-full rounded-[2px] border border-[var(--color-black)] bg-[var(--color-gold-light)] text-black shadow-none hover:border-[var(--color-gold)] hover:bg-[var(--color-warm-white)] hover:text-black"
            />
          </div>
        </div>
      ) : null}
    </header>
  );
}

