22	const bulkSchema = z.discriminatedUnion("action", [
23	  z.object({ action: z.literal("delete"), ids: z.array(z.string()).min(1) }),
24	  z.object({
25	    action: z.literal("setStatus"),
26	    ids: z.array(z.string()).min(1),
27	    status: z.enum(PRODUCT_STATUSES),
28	  }),
29	  z.object({
30	    action: z.literal("upsert"),
31	    products: z.array(productInputSchema).min(1),
32	  }),
33	]);
34	
35	export async function POST(request: NextRequest) {
36	  if (!isSupabaseConfigured()) return notConfigured();
37	
38	  const payload = await request.json().catch(() => null);
39	  const parsed = bulkSchema.safeParse(payload);
40	  if (!parsed.success) {
41	    return NextResponse.json(
42	      { error: "Invalid bulk request.", issues: parsed.error.flatten() },
43	      { status: 400 },
44	    );
...
40	  const supabase = createSupabaseServerClient();
41	  const body = parsed.data;
42	
43	  if (body.action === "delete") {
44	    const { error } = await supabase
45	      .from(PRODUCTS_TABLE)
46	      .delete()
47	      .in("id", body.ids);
48	    if (error) {
49	      if (isSupabaseSetupError(error)) return notConfigured();
50	      return NextResponse.json({ error: error.message }, { status: 500 });
51	    }
52	    return NextResponse.json({ ok: true, deleted: body.ids.length });
53	  }
54	
55	  if (body.action === "setStatus") {
56	    const { error } = await supabase
57	      .from(PRODUCTS_TABLE)
58	      .update({ status: body.status })
59	      .in("id", body.ids);
60	    if (error) {
61	      if (isSupabaseSetupError(error)) return notConfigured();
62	      return NextResponse.json({ error: error.message }, { status: 500 });
63	    }
64	    return NextResponse.json({ ok: true, updated: body.ids.length });
65	  }
66	
67	  // upsert (CSV import) — conflict on slug so re-imports update existing rows.
68	  const rows = body.products.map(inputToRow);
69	  const { data, error } = await supabase
70	    .from(PRODUCTS_TABLE)
71	    .upsert(rows, { onConflict: "slug" })
72	    .select("id");
73	
74	  if (error) {
75	    if (isSupabaseSetupError(error)) return notConfigured();
76	    return NextResponse.json({ error: error.message }, { status: 500 });
77	  }
78	  return NextResponse.json({ ok: true, upserted: data?.length ?? 0 });
79	}

