                  <div
                    key={`${image}-${index}`}
                    className="overflow-hidden border border-black/10 bg-[var(--color-warm-white)]"
                  >
                    <Image
                      src={image}
                      alt={`${product.title} view ${index + 2}`}
                      width={600}
                      height={600}
                      className="aspect-square w-full object-cover"
                    />
