S(H2("Design or wording changes to the pages"));
S(P("Changes to the actual page layout, copy, or features live in the website’s code. The workflow is:"));
S(step([t("The change is made in the code repository ("), new TextRun({ text: "website1", font: "Consolas", size: 19, color: INDIGO }), t(" on GitHub).")]));
S(step([t("It is pushed to GitHub (e.g. via "), t("GitHub Desktop", { bold: true }), t(").")]));
S(step([t("Vercel automatically builds and publishes the new version within a minute or two — no manual deploy needed.")]));
S(note("Who does this:", "Your technical support / developer handles code changes. You handle all content via the Catalog Manager."));

// 15. Supabase
S(H1("15.  Supabase — Database & Image Storage"));
