S(bullet("Products and categories."));
S(bullet("Projects."));
S(bullet("Every form submission (enquiries, newsletter, etc.)."));
S(bullet([t("Uploaded images, in the "), new TextRun({ text: "product-images", font: "Consolas", size: 19, color: INDIGO }), t(" storage bucket.")]));
S(H3("First-time / rebuild setup"));
S(P("If the database is ever set up fresh, three SQL scripts (kept in the code under the “supabase” folder) create the required tables. Run each once in the Supabase SQL editor:"));
S(table(
  ["Script", "Creates"],
  [
    ["schema.sql", "The form/enquiry tables (enquiries, newsletter, contact, etc.)."],
    ["catalog.sql", "The products and categories tables."],
    ["projects.sql", "The projects table for the Projects manager."],
  ],
  [2600, 6400],
));
S(spacer());
S(note("Access:", "Keep the Supabase account login secure. It contains all customer enquiry data and should be treated as confidential business information."));

// 16. Env vars
S(H1("16.  Settings & Secrets (Environment Variables)"));
S(P("The site depends on a small set of configuration values (“environment variables”), stored securely in Vercel — not in the code. Your technical support manages these:"));
S(table(
  ["Setting", "Purpose"],
  [
    ["NEXT_PUBLIC_SUPABASE_URL", "Address of your Supabase project."],
    ["NEXT_PUBLIC_SUPABASE_ANON_KEY", "Public key the website uses to read data."],
    ["SUPABASE_SERVICE_ROLE_KEY", "Secret admin key used by the server. Keep private."],
    ["ADMIN_PASSWORD", "The password for the Catalog Manager (/admin)."],
    ["ADMIN_SESSION_SECRET", "Secret used to keep admin logins secure."],
    ["NEXT_PUBLIC_WHATSAPP_NUMBER", "The WhatsApp number used by the site’s WhatsApp buttons."],
  ],
  [3900, 5100],
));

// 17. Security
S(H1("17.  Security Recommendations"));
S(note("Action recommended:", "During development, the admin password and the Supabase service-role key were shared over chat. Before or soon after go-live, rotate (change) both so only your team knows them."));
S(bullet([t("Change the "), t("admin password", { bold: true }), t(" in Vercel’s settings and share it only with trusted staff.")]));
S(bullet([t("Regenerate the "), t("Supabase service-role key", { bold: true }), t(" from the Supabase dashboard and update it in Vercel.")]));
S(bullet("Change the admin password whenever someone with access leaves."));
S(bullet("Never post these secrets in email, chat, or shared documents."));
S(bullet("Keep your domain, GitHub, Vercel, and Supabase account logins on strong, unique passwords with two-factor authentication."));

// 18. Troubleshooting
S(H1("18.  Troubleshooting"));
S(table(
  ["Symptom", "What to do"],
  [
    ["A product isn’t showing on the site", "Check its Status is “Active”, not “Draft”, and that it’s assigned to a category."],
    ["A collection page looks empty", "Assign products to that category/subcategory, or the page will show an “enquire / browse all” message."],
    ["An uploaded image won’t appear", "Re-upload it; confirm the save succeeded. Very unusual formats (e.g. HEIC) may need converting to JPG first."],
    ["A form submission didn’t arrive", "Check the correct tab in Responses; use search. If forms error site-wide, contact technical support (database may need attention)."],
    ["Enquiries tab is empty but you expected leads", "Confirm the site is live and forms were actually submitted; test by sending one enquiry yourself."],
    ["Changes to a page aren’t live", "Content changes are instant; code/design changes need to be pushed and auto-deployed by Vercel (Section 14)."],
  ],
  [3400, 5600],
));

// 19. Maintenance
S(H1("19.  Routine Maintenance"));
S(bullet("Weekly: check Responses for new enquiries and export a CSV backup."));
S(bullet("Keep product and project content and images up to date as your range evolves."));
S(bullet("Review the Privacy Policy and Terms pages periodically with your legal advisor."));
S(bullet("Renew your domain registration before it expires (a lapsed domain takes the site offline)."));
S(bullet("Ensure your Supabase and Vercel accounts remain active and in good standing."));

// 20. Support
S(H1("20.  Support & Key Accounts"));
S(P("Keep a private record of the logins and owners for each service the site relies on:"));
S(table(
  ["Service", "Used for", "Account owner"],
  [
    ["Domain registrar", "Your web address (domain).", "________________"],
    ["Vercel", "Website hosting & publishing.", "________________"],
    ["Supabase", "Database & image storage.", "________________"],
    ["GitHub", "The website’s source code.", "________________"],
    ["Technical support / developer", "Code changes, video updates, fixes.", "________________"],
  ],
  [2600, 3800, 2600],
));
S(spacer());
S(P([t("OSIMIRI contact on record:  ", { bold: true }),
   t("info@osimiri.in  ·  8050434040  ·  Bengaluru, Karnataka", {})]));

S(new Paragraph({ spacing: { before: 400 }, alignment: AlignmentType.CENTER,
  children: [t("— End of Handover Guide —", { italics: true, color: LIGHT }) ] }));

// ---------- document ----------
const doc = new Document({
  creator: "OSIMIRI",
  title: "OSIMIRI Website & Catalog Manager — Handover Guide",
  description: "Handover guide for the OSIMIRI website and admin tool",
  styles: { default: { document: { run: { font: FONT, size: 21, color: DARK } } } },
  numbering: {
    config: [
      { reference: "bullets", levels: [
        { level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { run: { color: GOLD }, paragraph: { indent: { left: 420, hanging: 220 } } } },
        { level: 1, format: LevelFormat.BULLET, text: "◦", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 820, hanging: 220 } } } },
      ] },
      { reference: "steps", levels: [
        { level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { run: { bold: true, color: BROWN }, paragraph: { indent: { left: 440, hanging: 260 } } } },
      ] },
    ],
  },
  sections: [
    { properties: { page: { margin: { top: 1100, bottom: 1100, left: 1200, right: 1200 } } }, children: cover },
    { properties: { page: { margin: { top: 1100, bottom: 1100, left: 1200, right: 1200 } } }, children: [...toc, ...body] },
  ],
});

Packer.toBuffer(doc).then((buf) => {
  const out = "/Users/feniljikadara/Documents/website1/OSIMIRI-Handover-Guide.docx";
  fs.writeFileSync(out, buf);
  console.log("WROTE", out, buf.length, "bytes");
});

