const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, BorderStyle, ShadingType,
  TableOfContents, PageBreak, ImageRun, LevelFormat, ExternalHyperlink,
} = require("docx");

// ---- brand palette ----
const BROWN = "6F4D38", GOLD = "B08D57", DARK = "20140C", GREY = "5B554D",
      INDIGO = "35347A", LIGHT = "8A857C", RULE = "D9D2C7";

const FONT = "Calibri", HEADFONT = "Georgia";

// ---------- helpers ----------
const t = (text, o = {}) => new TextRun({ text, font: o.font || FONT, size: o.size || 21, color: o.color || DARK, bold: o.bold, italics: o.italics });
const P = (children, o = {}) => new Paragraph({
  children: Array.isArray(children) ? children : [typeof children === "string" ? t(children, o) : children],
  spacing: { after: o.after ?? 120, before: o.before ?? 0, line: o.line ?? 276 },
  alignment: o.align, border: o.border, shading: o.shading, indent: o.indent,
});
const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 140 },
  children: [t(text, { font: HEADFONT, size: 30, bold: true, color: BROWN })],
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 6 } },
});
const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2, spacing: { before: 220, after: 90 },
  children: [t(text, { font: HEADFONT, size: 24, bold: true, color: DARK })],
});
const H3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3, spacing: { before: 160, after: 70 },
  children: [t(text, { font: HEADFONT, size: 21, bold: true, color: INDIGO })],
});
const bullet = (runs, lvl = 0) => new Paragraph({
  numbering: { reference: "bullets", level: lvl },
  spacing: { after: 70, line: 264 },
  children: Array.isArray(runs) ? runs : [t(runs)],
});
const step = (runs) => new Paragraph({
  numbering: { reference: "steps", level: 0 },
  spacing: { after: 70, line: 264 },
  children: Array.isArray(runs) ? runs : [t(runs)],
});
const note = (label, text) => new Paragraph({
  spacing: { before: 90, after: 120, line: 264 },
  shading: { type: ShadingType.CLEAR, fill: "F4EFE7", color: "auto" },
  border: {
    top: { style: BorderStyle.SINGLE, size: 2, color: GOLD },
    bottom: { style: BorderStyle.SINGLE, size: 2, color: GOLD },
    left: { style: BorderStyle.SINGLE, size: 18, color: GOLD },
    right: { style: BorderStyle.SINGLE, size: 2, color: GOLD },
  },
  indent: { left: 120, right: 120 },
  children: [t(label + "  ", { bold: true, color: BROWN }), t(text, { color: DARK })],
});
const code = (text) => new Paragraph({
  spacing: { after: 60, before: 20 },
  shading: { type: ShadingType.CLEAR, fill: "F3F1EC", color: "auto" },
  indent: { left: 120, right: 120 },
  children: [new TextRun({ text, font: "Consolas", size: 19, color: "3A3630" })],
});
const spacer = (h = 80) => new Paragraph({ spacing: { after: h }, children: [t("")] });

// tables
function cell(text, { w, header, bold, fill } = {}) {
  return new TableCell({
    width: { size: w, type: WidthType.DXA },
    shading: fill ? { type: ShadingType.CLEAR, fill, color: "auto" } : undefined,
    margins: { top: 60, bottom: 60, left: 110, right: 110 },
    children: [new Paragraph({
      spacing: { after: 0, line: 258 },
      children: Array.isArray(text) ? text : [t(text, { bold: bold || header, color: header ? "FFFFFF" : DARK, size: 20 })],
    })],
  });
}
function table(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const headRow = new TableRow({
    tableHeader: true,
    children: headers.map((h, i) => cell(h, { w: widths[i], header: true, fill: BROWN })),
  });
  const bodyRows = rows.map((r, ri) => new TableRow({
    children: r.map((c, i) => cell(c, { w: widths[i], fill: ri % 2 ? "FAF8F4" : "FFFFFF" })),
  }));
  return new Table({
    columnWidths: widths,
    width: { size: total, type: WidthType.DXA },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: RULE },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: RULE },
      left: { style: BorderStyle.SINGLE, size: 2, color: RULE },
      right: { style: BorderStyle.SINGLE, size: 2, color: RULE },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2, color: RULE },
      insideVertical: { style: BorderStyle.SINGLE, size: 2, color: RULE },
    },
    rows: [headRow, ...bodyRows],
  });
}

// ---------- cover ----------
const cover = [];
try {
  const logo = fs.readFileSync("/Users/feniljikadara/Documents/website1/public/logo-removebg-preview.png");
  cover.push(new Paragraph({
    alignment: AlignmentType.CENTER, spacing: { before: 1400, after: 200 },
    children: [new ImageRun({ type: "png", data: logo, transformation: { width: 240, height: 150 } })],
  }));
} catch (e) {
  cover.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 1600, after: 120 },
    children: [t("OSIMIRI", { font: HEADFONT, size: 64, bold: true, color: BROWN })] }));
}
cover.push(
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 60 },
    children: [t("Website & Catalog Manager", { font: HEADFONT, size: 40, bold: true, color: DARK })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 40 },
    children: [t("HANDOVER GUIDE", { font: FONT, size: 30, bold: true, color: GOLD })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 500 },
    children: [t("Everything you need to run, update, and maintain your website", { italics: true, color: GREY, size: 22 })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 30 },
    children: [t("Prepared for:  OSIMIRI — Luxury Furniture", { color: DARK, size: 22 })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 30 },
    children: [t("Bengaluru, India", { color: GREY, size: 20 })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 700 },
    children: [t("Document version 1.0", { color: LIGHT, size: 18 })] }),
  new Paragraph({ children: [new PageBreak()] }),
);

// ---------- TOC ----------
const toc = [
  new Paragraph({ spacing: { after: 140 }, children: [t("Contents", { font: HEADFONT, size: 30, bold: true, color: BROWN })] }),
  new TableOfContents("Contents", { hyperlink: true, headingStyleRange: "1-2" }),
  new Paragraph({ children: [new PageBreak()] }),
];

// ---------- body ----------
const body = [];
const S = (...items) => body.push(...items);

// 1. Introduction
S(H1("1.  Introduction"));
S(P("This guide is a complete, plain-language handover for the OSIMIRI website and its built-in content management tool (the “Catalog Manager”). It explains what you have received, how to update everything yourself, how changes go live, and how to keep the site healthy over time."));
S(P("You do not need to be a developer to run the day-to-day parts of the site — adding products, projects, categories, reading enquiries, and publishing changes are all done through a simple admin panel in your browser. The more technical sections (database, deployment, secrets) are included for whoever provides your ongoing technical support."));
S(note("How to use this guide:", "Sections 4–10 are your everyday operating manual. Sections 11–20 cover the technical setup, security, and troubleshooting. Keep this document somewhere safe — it also lists the accounts and settings the site depends on."));

// 2. What's included
S(H1("2.  What You Have Received"));
S(P("Your delivery consists of the following:"));
S(bullet([t("A public marketing website", { bold: true }), t(" — a fast, modern, mobile-friendly website with your collections, products, projects, manufacturing story, and enquiry forms.")]));
S(bullet([t("A Catalog Manager (admin panel)", { bold: true }), t(" — a private, password-protected area of the site where you manage products, projects, categories, images, and read every enquiry customers send.")]));
S(bullet([t("A cloud database and image storage", { bold: true }), t(" — all your products, projects, and form submissions are stored in Supabase, a secure hosted database, with images stored in cloud storage.")]));
S(bullet([t("Automatic hosting and publishing", { bold: true }), t(" — the site is hosted on Vercel and re-publishes automatically whenever changes are approved.")]));
S(bullet([t("This handover guide.", { bold: true })]));

// 3. How it fits together
S(H1("3.  How the System Fits Together"));
S(P("Four services work together. You mostly only touch the first one:"));
S(table(
  ["Piece", "What it does", "Who touches it"],
  [
    ["Catalog Manager (/admin)", "Where you add products, projects, categories; read enquiries.", "You, day-to-day"],
    ["The website", "What your customers see. Reads its content from the database.", "Automatic"],
    ["Supabase", "The cloud database + image storage that holds all content and enquiries.", "Rarely — technical support"],
    ["Vercel", "The host that serves the website and re-publishes updates.", "Rarely — technical support"],
  ],
  [2600, 4400, 2000],
));
S(spacer());
S(P([t("In short: ", { bold: true }), t("you make changes in the Catalog Manager → they are saved to Supabase → the website shows them. Design or wording changes to the pages themselves go through the code and are published via Vercel (see Section 14).")]));

// 4. Accessing the admin
S(H1("4.  Accessing the Catalog Manager"));
S(step([t("In your web browser, go to your website address followed by ", {}), new TextRun({ text: "/admin", font: "Consolas", size: 19, color: INDIGO }), t("  (for example, ", {}), new TextRun({ text: "https://your-domain.com/admin", font: "Consolas", size: 19, color: INDIGO }), t(").")]));
S(step("Enter the admin password when prompted. You stay signed in on that browser until you log out."));
S(step("You will land on the Overview dashboard. Use the left-hand menu to move between sections."));
S(note("Keep it private:", "Anyone with the admin password can edit your site and read customer enquiries. Share it only with trusted staff, and change it if someone leaves (see Section 16–17)."));
S(H3("The menu at a glance"));
S(table(
  ["Menu item", "What it is for"],
  [
    ["Overview", "A snapshot: number of products, drafts, categories, and recent activity."],
    ["Products", "Add, edit, publish, and delete catalogue products."],
    ["Projects", "Add, edit, and delete portfolio projects shown on the Projects page."],
    ["Categories", "Manage the collection categories and subcategories."],
    ["Media Library", "All uploaded images in one place."],
    ["Responses", "Every enquiry and newsletter sign-up from the website’s forms."],
    ["Activity Log", "A record of recent changes made in the tool."],
  ],
  [2600, 6400],
));

// 5. Products
S(H1("5.  Managing Products"));
S(H2("Adding a product"));
S(step("Go to Products → click “Add product”."));
S(step([t("Fill in the "), t("Title", { bold: true }), t(" (required). The web address (“slug”) is filled in for you automatically from the title.")]));
S(step([t("Add a "), t("Short description", { bold: true }), t(" (shown on listing cards) and a "), t("Full description", { bold: true }), t(" (shown on the product page).")]));
S(step([t("Under "), t("Media", { bold: true }), t(", upload a "), t("Main image", { bold: true }), t(" (used on cards and as the hero) plus optional Gallery, Lifestyle, and Detail images. See Section 11 for how images are handled.")]));
S(step([t("On the right, set the "), t("Status", { bold: true }), t(" (Draft keeps it hidden; Active publishes it), choose a "), t("Category", { bold: true }), t(" and "), t("Subcategory", { bold: true }), t(", and optionally a Collection and Price.")]));
S(step("Click “Create product”. It appears in your catalogue immediately once the status is Active."));
S(H2("Editing or deleting"));
S(bullet("Open Products, click any product to edit it, make your changes, then “Save changes”."));
S(bullet("To remove a product, open it and click “Delete” (this cannot be undone)."));
S(H2("The multi-value fields (finishes, tags, materials)"));
S(P([t("Fields such as Finish options, Secondary materials, and the various Tags accept several values. Type a value and press "), t("Enter", { bold: true }), t(" or a "), t("comma", { bold: true }), t(" to turn it into a chip. Click the × on a chip to remove it. Pressing Enter here will "), t("not", { italics: true }), t(" accidentally save or leave the page.")]));
S(H2("Product ID / SKU"));
S(P("The Product ID / SKU is generated automatically when you save — you do not type it in. If you would prefer to enter your own SKUs manually, this can be enabled on request."));
S(note("Tip:", "Set a product to “Draft” while you are still preparing it, then switch to “Active” when it is ready to appear on the website."));

// 6. Projects
S(H1("6.  Managing Projects"));
S(P("Projects are the portfolio entries shown on the Projects page and the homepage. They are fully editable in the tool."));
S(H2("Adding or editing a project"));
S(step("Go to Projects. Existing projects are listed; click one to edit, or click “Add project” for a new one."));
S(step([t("Fill in "), t("Title", { bold: true }), t(", "), t("Location", { bold: true }), t(", "), t("Type", { bold: true }), t(" (e.g. “Bespoke Luxury”), and a "), t("Description", { bold: true }), t(".")]));
S(step([t("Upload a "), t("Hero image", { bold: true }), t(" (the lead image for the project) and one or more "), t("Project slides", { bold: true }), t(" (shown in order down the project’s section).")]));
S(step("Save. The project appears on the website immediately."));
S(note("Good to know:", "As soon as you have at least one project saved in the tool, the website shows your saved projects instead of the built-in samples. Your 8 current projects (Eira, Ikigai, Calm, Serene, Casa, Noir, Hunkal, Beads Bliss) are already loaded and editable."));

// 7. Categories
S(H1("7.  Managing Categories"));
S(P("Categories power the Collections on the website and the Category/Subcategory choices on each product."));
S(bullet("Open Categories to add, rename, or remove a category or subcategory."));
S(bullet("Categories can have subcategories (for example, “Foyer” → “Consoles”, “Mirrors”)."));
S(bullet([t("When editing a product, choose the top-level "), t("Category", { bold: true }), t(" first; the "), t("Subcategory", { bold: true }), t(" list then fills with that category’s subcategories.")]));
S(note("Note:", "A collection page (e.g. “Center Table”) shows the products whose category matches it. If a collection looks empty, make sure your products are assigned to that category/subcategory."));

// 8. Media
S(H1("8.  Media Library"));
S(P("The Media Library shows every image you have uploaded across products and projects, so you can review and reuse them. Images are stored securely in the cloud (Supabase Storage) and served to the website automatically."));

// 9. Responses
S(H1("9.  Responses — Website Enquiries & Leads"));
S(P("Every form on the website saves its submissions to your database, and you can read them all under Responses. This is where your sales leads live."));
S(H3("The forms captured here"));
S(table(
  ["Tab", "Comes from"],
  [
    ["Enquiries", "The main “Enquire / Send Enquiry” forms across the site and product pages."],
    ["Custom Furniture", "The custom furniture enquiry form."],
    ["Architects", "The architects & designers enquiry form."],
    ["Contact", "The Contact page form."],
    ["Appointments", "Experience-centre / “Book a visit” appointment requests."],
    ["Newsletter", "Footer newsletter sign-ups."],
  ],
  [2600, 6400],
));
S(spacer());
S(bullet("Switch between forms using the tabs; each shows the newest submissions first."));
S(bullet("Use the search box to find a name, phone, email, or city."));
S(bullet([t("Click "), t("Export CSV", { bold: true }), t(" to download that form’s submissions as a spreadsheet (opens in Excel / Google Sheets).")]));
S(bullet("Email addresses and phone numbers are clickable, so you can reply or call directly."));
S(note("Important:", "Respond to enquiries promptly — they are genuine leads. Consider exporting the CSV weekly as a backup and to work leads in your own CRM or spreadsheet."));

// 10. Activity log
S(H1("10.  Activity Log"));
S(P("The Activity Log records recent actions taken in the Catalog Manager — products created, updated, published, or images uploaded — so you can see what changed and when. It is a helpful audit trail if more than one person manages the catalogue."));

// 11. Images & video
S(H1("11.  Images & Videos — How Uploads Work"));
S(P("You do not need to resize or compress images before uploading. The system does it for you:"));
S(bullet([t("Every uploaded image is "), t("automatically resized and compressed", { bold: true }), t(" to load fast on the website while staying good quality (kept well under 1 MB).")]));
S(bullet([t("It happens in the right order — "), t("resize first, then compress", {}), t(" — and the image is also auto-rotated if needed.")]));
S(bullet([t("Large photos work fine. Files are shrunk in your browser "), t("before", { italics: true }), t(" they upload, so even 6–15 MB camera photos upload reliably.")]));
S(bullet("Add descriptive Alt text on the main product image for accessibility and search engines."));
S(H3("Videos"));
S(P("The homepage hero and the Manufacturing page use short background videos (your Experience Centre and factory footage). These are part of the site build. To change a video, send the new clip to your technical support and they will optimise and publish it (videos need compression the browser tool does not do)."));
S(note("Best practice:", "Upload the best-quality original you have. The system makes the web-optimised version. Landscape photos generally look best as hero/lead images; portrait photos work well in galleries."));

// 12. Website tour
S(H1("12.  The Website Pages"));
S(P("Your public site includes the following pages:"));
S(table(
  ["Page", "What it shows"],
  [
    ["Home", "Hero video, brand statement, OSIMIRI Advantages, collections, featured projects, manufacturing, testimonials."],
    ["Collections", "The category collections; each links to its filtered products."],
    ["Products", "The full catalogue, grouped by category, with a detail page per product (image gallery, specs, enquiry)."],
    ["Projects", "Your portfolio — hero image and slides per project."],
    ["Custom Furniture", "The bespoke offering with its own enquiry form."],
    ["Manufacturing", "Factory video hero and the in-house capabilities (wood, metal, marble, upholstery)."],
    ["Architects", "The partner-first message and the practices you have worked with."],
    ["About", "Brand story, founders, mission, vision."],
    ["Contact", "Contact details and a contact form."],
    ["Search", "Live search across products, collections, and projects."],
    ["Blogs", "Article listing and individual article pages."],
    ["Privacy / Terms", "Your legal pages."],
  ],
  [2400, 6600],
));

// 13. Forms
S(H1("13.  Forms & Where Submissions Go"));
S(P("All website forms validate the visitor’s input, then save to your database and appear under Responses (Section 9). If the database is ever temporarily unavailable, visitors are shown a friendly message directing them to email or WhatsApp you, so no lead is lost to a confusing error."));

// 14. Deployment
S(H1("14.  Publishing Changes & Deployment"));
S(H2("Content changes (products, projects, enquiries)"));
S(P("These are live instantly. When you save in the Catalog Manager, the change is written to the database and the website reflects it right away — no publishing step needed."));
S(H2("Design or wording changes to the pages"));
S(P("Changes to the actual page layout, copy, or features live in the website’s code. The workflow is:"));
