));

// 17. Security
S(H1("17.  Security Recommendations"));
S(note("Action recommended:", "During development, the admin password and the Supabase service-role key were shared over chat. Before or soon after go-live, rotate (change) both so only your team knows them."));
S(bullet([t("Change the "), t("admin password", { bold: true }), t(" in Vercel’s settings and share it only with trusted staff.")]));
S(bullet([t("Regenerate the "), t("Supabase service-role key", { bold: true }), t(" from the Supabase dashboard and update it in Vercel.")]));
S(bullet("Change the admin password whenever someone with access leaves."));
S(bullet("Never post these secrets in email, chat, or shared documents."));
S(bullet("Keep your domain, GitHub, Vercel, and Supabase account logins on strong, unique passwords with two-factor authentication."));

// 18. Troubleshooting
S(H1("18.  Troubleshooting"));
S(table(
  ["Symptom", "What to do"],
  [
    ["A product isn’t showing on the site", "Check its Status is “Active”, not “Draft”, and that it’s assigned to a category."],
    ["A collection page looks empty", "Assign products to that category/subcategory, or the page will show an “enquire / browse all” message."],
