const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, BorderStyle, ShadingType,
  PageBreak, Header, Footer, PageNumber, ImageRun, LevelFormat,
} = require("docx");

const FONT = "Calibri";
const H_BLUE = "2E74B5", H_DARK = "1F4D78", INK = "222222", GREY = "595959", RULE = "BFBFBF";
const HEADFILL = "2E74B5", ALT = "F3F7FC", METALABEL = "44546A";
const CW = 9360; // content width at 1" margins on Letter

// ---------- inline / paragraph helpers ----------
const t = (text, o = {}) => new TextRun({ text, font: FONT, size: o.size || 22, color: o.color || INK, bold: o.bold, italics: o.italics });
const mono = (text) => new TextRun({ text, font: "Consolas", size: 20, color: "1F4D78" });
const P = (children, o = {}) => new Paragraph({
  children: Array.isArray(children) ? children : [typeof children === "string" ? t(children, o) : children],
  spacing: { after: o.after ?? 130, before: o.before ?? 0, line: 278 }, alignment: o.align,
});
const H1 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [t(text, { size: 32, bold: true, color: H_BLUE })] });
const H2 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [t(text, { size: 26, bold: true, color: H_BLUE })] });
const H3 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_3, children: [t(text, { size: 24, bold: true, color: H_DARK })] });
const bullet = (runs, lvl = 0) => new Paragraph({ numbering: { reference: "b", level: lvl }, spacing: { after: 60, line: 268 }, children: Array.isArray(runs) ? runs : [t(runs)] });
const step = (runs) => new Paragraph({ numbering: { reference: "s", level: 0 }, spacing: { after: 60, line: 268 }, children: Array.isArray(runs) ? runs : [t(runs)] });
const note = (label, text) => new Paragraph({
  spacing: { before: 80, after: 130, line: 268 }, indent: { left: 120, right: 120 },
  shading: { type: ShadingType.CLEAR, fill: "FBF6E9", color: "auto" },
  border: { left: { style: BorderStyle.SINGLE, size: 20, color: "C9A227" }, top: { style: BorderStyle.SINGLE, size: 2, color: "E6D9A8" }, bottom: { style: BorderStyle.SINGLE, size: 2, color: "E6D9A8" }, right: { style: BorderStyle.SINGLE, size: 2, color: "E6D9A8" } },
  children: [t(label + "  ", { bold: true, color: "8A6D1F" }), t(text)],
});
const spacer = (h = 60) => new Paragraph({ spacing: { after: h }, children: [t("")] });

// ---------- tables ----------
const NOBORDER = { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE }, insideHorizontal: { style: BorderStyle.NONE }, insideVertical: { style: BorderStyle.NONE } };
const GRID = (c) => ({ style: BorderStyle.SINGLE, size: 2, color: c || RULE });
function tc(content, { w, fill, header, bold, alignRight } = {}) {
  const runs = Array.isArray(content) ? content : [t(content, { bold: bold || header, color: header ? "FFFFFF" : INK, size: 20 })];
  return new TableCell({
    width: { size: w, type: WidthType.DXA },
    shading: fill ? { type: ShadingType.CLEAR, fill, color: "auto" } : undefined,
    margins: { top: 55, bottom: 55, left: 110, right: 110 },
    children: [new Paragraph({ spacing: { after: 0, line: 256 }, alignment: alignRight ? AlignmentType.RIGHT : undefined, children: runs })],
  });
}
function dataTable(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const head = new TableRow({ tableHeader: true, children: headers.map((h, i) => tc(h, { w: widths[i], header: true, fill: HEADFILL })) });
  const body = rows.map((r, ri) => new TableRow({ children: r.map((c, i) => tc(c, { w: widths[i], fill: ri % 2 ? ALT : "FFFFFF" })) }));
  return new Table({ columnWidths: widths, width: { size: total, type: WidthType.DXA },
    borders: { top: GRID(), bottom: GRID(), left: GRID(), right: GRID(), insideHorizontal: GRID("D8D8D8"), insideVertical: GRID("D8D8D8") },
    rows: [head, ...body] });
}
// borderless label/value block (cover metadata + contents)
function kvTable(rows, wLabel, wValue) {
  return new Table({ columnWidths: [wLabel, wValue], width: { size: wLabel + wValue, type: WidthType.DXA }, borders: NOBORDER,
    rows: rows.map((r) => new TableRow({ children: [
      tc([t(r[0], { bold: true, color: METALABEL, size: 20 })], { w: wLabel }),
      tc(Array.isArray(r[1]) ? r[1] : [t(r[1], { size: 21 })], { w: wValue }),
    ] })) });
}

// ================= COVER =================
const cover = [];
try {
  const logo = fs.readFileSync("/Users/feniljikadara/Documents/website1/public/logo-removebg-preview.png");
  cover.push(new Paragraph({ spacing: { before: 400, after: 260 }, children: [new ImageRun({ type: "png", data: logo, transformation: { width: 168, height: 105 } })] }));
} catch (e) { cover.push(spacer(400)); }
cover.push(
  new Paragraph({ spacing: { after: 60 }, children: [t("WEBSITE HANDOVER & OPERATIONS GUIDE", { size: 20, bold: true, color: H_BLUE })] }),
  new Paragraph({ spacing: { after: 40 }, children: [t("OSIMIRI Website & Catalog Manager", { size: 52, bold: true, color: INK })] }),
  new Paragraph({ spacing: { after: 300 }, border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: "C9A227", space: 8 } }, children: [t("User Guide and Technical Reference", { size: 26, color: GREY })] }),
  kvTable([
    ["Prepared for", "OSIMIRI — Luxury Furniture, Bengaluru"],
    ["Document version", "1.0"],
    ["Date", "31 August 2026"],
    ["Platform", [mono("Next.js"), t(" (App Router) on "), mono("Vercel"), t("  ·  "), mono("Supabase"), t(" database & storage")]],
    ["Admin tool", [t("Catalog Manager — accessed at "), mono("/admin")]],
    ["Status at issue", "Live and in use."],
    ["Audience", "Part A: OSIMIRI staff (no technical background). Part B: whoever maintains the website."],
  ], 2600, 6760),
  new Paragraph({ children: [new PageBreak()] }),
);

// ================= BODY =================
const body = [];
const S = (...x) => body.push(...x);

// How to read
S(H1("How to read this document"));
S(P("This guide is in two parts, written for two different readers. Neither part assumes you have read the other."));
S(dataTable(
  ["Part", "Who it is for", "What it answers"],
  [
    ["Part A — User Guide", "OSIMIRI staff who run the site day to day. No technical background assumed.", "How to sign in, add and edit products and projects, manage categories and images, read enquiries, and the monthly routine."],
    ["Part B — Technical Reference", "Whoever maintains, debugs, or extends the website.", "Architecture, accounts and settings, database and storage, the image pipeline, deployment, business rules, known limitations, and a troubleshooting runbook."],
  ],
  [2400, 3200, 3760],
));
S(spacer());

// Contents
S(H3("Contents"));
S(new Paragraph({ spacing: { after: 60 }, children: [t("Part A", { bold: true, color: H_BLUE, size: 22 }), t("   User Guide", { color: GREY, size: 22 })] }));
S(kvTable([
  ["A1", "What the website and Catalog Manager are"],
  ["A2", "Signing in to the Catalog Manager"],
  ["A3", "Adding and editing products"],
  ["A4", "Adding and editing projects"],
  ["A5", "Categories and collections"],
  ["A6", "Images and video"],
  ["A7", "Reading enquiries — the Responses inbox"],
  ["A8", "Media Library and Activity Log"],
  ["A9", "The website pages at a glance"],
  ["A10", "Your monthly routine and responsibilities"],
  ["A11", "What the tool deliberately does not do"],
], 700, 8660));
S(new Paragraph({ spacing: { before: 120, after: 60 }, children: [t("Part B", { bold: true, color: H_BLUE, size: 22 }), t("   Technical Reference", { color: GREY, size: 22 })] }));
S(kvTable([
  ["B1", "System identity and architecture"],
  ["B2", "Accounts, environments and settings"],
  ["B3", "Database and storage (Supabase)"],
  ["B4", "Forms and the Responses data flow"],
  ["B5", "The image pipeline"],
  ["B6", "Deployment and publishing"],
  ["B7", "Business rules and configuration points"],
  ["B8", "Known limitations and gotchas"],
  ["B9", "Failure modes and troubleshooting runbook"],
  ["B10", "Security and change control"],
  ["B11", "Appendix — routes and quick reference"],
], 700, 8660));
S(new Paragraph({ children: [new PageBreak()] }));

// ===================== PART A =====================
S(H1("Part A — User Guide"));
S(P("This part is for anyone at OSIMIRI who keeps the website up to date. Everything here is done in your web browser; no software to install."));

S(H2("A1.  What the website and Catalog Manager are"));
S(P("You have two things working together:"));
S(bullet([t("The website", { bold: true }), t(" — the public site your customers visit: collections, products, projects, the manufacturing story, and enquiry forms.")]));
S(bullet([t("The Catalog Manager", { bold: true }), t(" — a private, password-protected admin area of the same site where you add and edit content and read every enquiry.")]));
S(P([t("When you save something in the Catalog Manager it is stored in a secure cloud database and appears on the website "), t("immediately", { bold: true }), t(" — there is no separate “publish” button for content.")]));

S(H2("A2.  Signing in to the Catalog Manager"));
S(step([t("Go to your website address followed by "), mono("/admin"), t("  (for example "), mono("https://your-domain.com/admin"), t(").")]));
S(step("Enter the admin password. You stay signed in on that browser until you log out."));
S(step("Use the left-hand menu to move between sections. On a phone, tap the menu icon."));
S(note("Keep it private:", "Anyone with the admin password can edit the site and read customer enquiries. Share it only with trusted staff, and have it changed when someone leaves (see B10)."));
S(P("The menu:"));
S(dataTable(["Menu item", "What it is for"], [
  ["Overview", "A snapshot: products, drafts, categories, and recent activity."],
  ["Products", "Add, edit, publish, and delete catalogue products."],
  ["Projects", "Add, edit, and delete portfolio projects."],
  ["Categories", "Manage collection categories and subcategories."],
  ["Media Library", "All uploaded images in one place."],
  ["Responses", "Every enquiry and newsletter sign-up from the website forms."],
  ["Activity Log", "A record of recent changes made in the tool."],
], [2500, 6860]));

S(H2("A3.  Adding and editing products"));
S(H3("Add a product"));
