const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, BorderStyle, ShadingType,
  PageBreak, Header, Footer, PageNumber, LevelFormat,
} = require("docx");

const FONT = "Calibri";
const H_BLUE = "2E74B5", H_DARK = "1F4D78", INK = "222222", GREY = "595959", RULE = "BFBFBF";
const HEADFILL = "2E74B5", ALT = "F3F7FC", METALABEL = "44546A", ACCENT = "C9A227";
const OUTDIR = "/Users/feniljikadara/Documents/website1/handover";

// ---------- inline / paragraph helpers ----------
const t = (text, o = {}) => new TextRun({ text, font: FONT, size: o.size || 22, color: o.color || INK, bold: o.bold, italics: o.italics });
const mono = (text) => new TextRun({ text, font: "Consolas", size: 20, color: H_DARK });
const P = (children, o = {}) => new Paragraph({ children: Array.isArray(children) ? children : [typeof children === "string" ? t(children, o) : children], spacing: { after: o.after ?? 130, before: o.before ?? 0, line: 278 }, alignment: o.align });
const H1 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [t(text, { size: 30, bold: true, color: H_BLUE })] });
const H2 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [t(text, { size: 25, bold: true, color: H_BLUE })] });
const H3 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_3, children: [t(text, { size: 23, bold: true, color: H_DARK })] });
const bullet = (runs, lvl = 0) => new Paragraph({ numbering: { reference: "b", level: lvl }, spacing: { after: 60, line: 268 }, children: Array.isArray(runs) ? runs : [t(runs)] });
const step = (runs) => new Paragraph({ numbering: { reference: "s", level: 0 }, spacing: { after: 60, line: 268 }, children: Array.isArray(runs) ? runs : [t(runs)] });
const note = (label, text) => new Paragraph({ spacing: { before: 80, after: 130, line: 268 }, indent: { left: 120, right: 120 }, shading: { type: ShadingType.CLEAR, fill: "FBF6E9", color: "auto" }, border: { left: { style: BorderStyle.SINGLE, size: 20, color: ACCENT }, top: { style: BorderStyle.SINGLE, size: 2, color: "E6D9A8" }, bottom: { style: BorderStyle.SINGLE, size: 2, color: "E6D9A8" }, right: { style: BorderStyle.SINGLE, size: 2, color: "E6D9A8" } }, children: [t(label + "  ", { bold: true, color: "8A6D1F" }), t(text)] });
const spacer = (h = 60) => new Paragraph({ spacing: { after: h }, children: [t("")] });

// ---------- tables ----------
const NOBORDER = { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE }, insideHorizontal: { style: BorderStyle.NONE }, insideVertical: { style: BorderStyle.NONE } };
const GRID = (c) => ({ style: BorderStyle.SINGLE, size: 2, color: c || RULE });
function tc(content, { w, fill, header, bold, alignRight } = {}) {
  const runs = Array.isArray(content) ? content : [t(content, { bold: bold || header, color: header ? "FFFFFF" : INK, size: 20 })];
  return new TableCell({ width: { size: w, type: WidthType.DXA }, shading: fill ? { type: ShadingType.CLEAR, fill, color: "auto" } : undefined, margins: { top: 55, bottom: 55, left: 110, right: 110 }, children: [new Paragraph({ spacing: { after: 0, line: 256 }, alignment: alignRight ? AlignmentType.RIGHT : undefined, children: runs })] });
}
function dataTable(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const head = new TableRow({ tableHeader: true, children: headers.map((h, i) => tc(h, { w: widths[i], header: true, fill: HEADFILL })) });
  const body = rows.map((r, ri) => new TableRow({ children: r.map((c, i) => tc(c, { w: widths[i], fill: ri % 2 ? ALT : "FFFFFF" })) }));
  return new Table({ columnWidths: widths, width: { size: total, type: WidthType.DXA }, borders: { top: GRID(), bottom: GRID(), left: GRID(), right: GRID(), insideHorizontal: GRID("D8D8D8"), insideVertical: GRID("D8D8D8") }, rows: [head, ...body] });
}
function kvTable(rows, wLabel, wValue) {
  return new Table({ columnWidths: [wLabel, wValue], width: { size: wLabel + wValue, type: WidthType.DXA }, borders: NOBORDER, rows: rows.map((r) => new TableRow({ children: [tc([t(r[0], { bold: true, color: METALABEL, size: 20 })], { w: wLabel }), tc(Array.isArray(r[1]) ? r[1] : [t(r[1], { size: 21 })], { w: wValue })] })) });
}

